-- V38 workspace migration candidate: AUTHORED_NOT_EXECUTED. Seven tables, 39 original columns.
-- Existing distinct source/target schemas, stopped source and target writers, explicit evidenced source DATETIME offset.
-- Target baseline/relations already installed. Source grants SELECT+TRIGGER permit complete read-only metadata checks.
-- Private bytes remain at their existing users/{owner}/{file_id}.bin path; separately verify/copy the private volume.
-- All old row IDs stay in legacy provenance. New shared cursors do not inherit per-source AUTO_INCREMENT.
-- Preserve each original source sequence in the migration receipt/backup. Never write or drop source data.
-- Source request/fork rows have no timestamps: their receipt times remain NULL, not guessed from import time.
-- One connection, stop at first error, ROLLBACK there then close. Never --force.
SET NAMES utf8mb4;
CREATE TEMPORARY TABLE compact_workspace_guard(valid INT NOT NULL CHECK(valid=1)) ENGINE=InnoDB;
CREATE TEMPORARY TABLE compact_workspace_columns(table_name VARCHAR(64),column_name VARCHAR(64),ordinal_position INT,column_type VARCHAR(64),nullable VARCHAR(3),collation_name VARCHAR(64),default_value VARCHAR(64),extra VARCHAR(64),PRIMARY KEY(table_name,column_name)) ENGINE=InnoDB;
CREATE TEMPORARY TABLE compact_workspace_keys(table_name VARCHAR(64),is_primary BOOLEAN,key_columns VARCHAR(1024)) ENGINE=InnoDB;
START TRANSACTION;
CREATE TEMPORARY TABLE compact_workspace_session_snapshot(`id` BIGINT NOT NULL,`session_id` VARCHAR(64) COLLATE utf8mb4_unicode_ci NOT NULL,`username` VARCHAR(64) COLLATE utf8mb4_unicode_ci NOT NULL,`user_id` BIGINT NOT NULL,`project_id` VARCHAR(64) COLLATE utf8mb4_unicode_ci NULL,`title` VARCHAR(255) COLLATE utf8mb4_unicode_ci NULL,`status` VARCHAR(32) COLLATE utf8mb4_unicode_ci NOT NULL,`pinned` BOOLEAN NULL,`state_json` LONGTEXT COLLATE utf8mb4_unicode_ci NULL,`checkpoint_version` INT NOT NULL,`checkpoint_node` VARCHAR(64) COLLATE utf8mb4_unicode_ci NULL,`checkpoint_exit_reason` VARCHAR(64) COLLATE utf8mb4_unicode_ci NULL,`checkpoint_updated_at` DATETIME NULL,`created_at` DATETIME NULL,`updated_at` DATETIME NULL,PRIMARY KEY(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TEMPORARY TABLE compact_workspace_fork_projection(legacy_id DECIMAL(20,0) PRIMARY KEY,target_id BIGINT NOT NULL UNIQUE) ENGINE=InnoDB;
UPDATE content_asset SET current_version=1,lifecycle='ACTIVE' WHERE asset_kind='WORKSPACE_FILE';
UPDATE chat_session t JOIN compact_workspace_fork_projection expected ON expected.target_id=t.id JOIN `__SOURCE_SCHEMA__`.agent_session_fork s ON s.id=expected.legacy_id AND BINARY t.session_id=BINARY s.fork_session_id AND t.user_id=s.user_id SET t.fork_owner_user_id=s.user_id,t.fork_request_id=s.request_id,t.fork_source_session_id=s.source_session_id,t.fork_through_message_id=s.through_message_id,t.fork_legacy_id=s.id,t.updated_at=t.updated_at;
COMMIT;
DROP TEMPORARY TABLE compact_workspace_fork_projection;
DROP TEMPORARY TABLE compact_workspace_session_snapshot;
DROP TEMPORARY TABLE compact_workspace_keys;
DROP TEMPORARY TABLE compact_workspace_columns;
DROP TEMPORARY TABLE compact_workspace_guard;
